from gigachat import GigaChat

from backend.core.config import settings


class LLMClient:
    def __init__(self) -> None:
        if not settings.gigachat_credentials:
            raise ValueError(
                "GIGACHAT_CREDENTIALS не задан в .env. "
                "Укажите ключ авторизации GigaChat."
            )

        self.credentials = settings.gigachat_credentials
        self.model = settings.gigachat_model
        self.verify_ssl_certs = settings.gigachat_verify_ssl_certs

    def generate_answer(self, question: str, context: str) -> str:
        prompt = self._build_prompt(question=question, context=context)

        with GigaChat(
            credentials=self.credentials,
            verify_ssl_certs=self.verify_ssl_certs,
        ) as client:
            response = client.chat(
                {
                    "model": self.model,
                    "messages": [
                        {
                            "role": "system",
                            "content": (
                                "Ты помощник для анализа сертификатов и деклараций "
                                "соответствия. Отвечай только на основе переданного "
                                "контекста. Если данных недостаточно, прямо скажи об этом. "
                                "Не придумывай факты. "
                                "Если вопрос содержит ограничения по типу документа, статусу, дате или актуальности, "
                                "обязательно проверь эти признаки по каждому найденному документу. "
                                "Не называй документ подходящим, если он не соответствует явному ограничению пользователя. "
                                "Если найденные документы частично не соответствуют запросу, прямо скажи об этом. "
                                "Если пользователь спрашивает только сертификаты, а среди источников есть декларации, "
                                "укажи, что декларации не являются сертификатами. "
                                "Если пользователь спрашивает об актуальности, учитывай статус документа и срок действия. "
                                "Если статус документа равен 'Архивный', не называй документ актуальным. "
                                "Если пользователь спрашивает про сертификаты, декларация не может считаться полностью подходящим результатом, "
                                "даже если она действующая. В таком случае укажи, что декларация является только связанным или частично подходящим документом. "
                                "Не перечисляй найденные документы в формате 'Документ 1', 'Документ 2', "
                                "если эти документы уже будут показаны пользователю в карточках источников. "
                                "Не дублируй все поля документов из контекста. "
                                "В основном ответе дай аналитическое объяснение обычным текстом: "
                                "какие результаты подходят полностью, какие подходят частично и почему. "
                                "Если среди найденных документов нет полностью подходящих результатов, итоговый вывод должен начинаться словами: "
                                "'Среди найденных документов полностью подходящих результатов не обнаружено'. "
                                "В конце ответа кратко сформулируй вывод: есть ли среди найденных документов полностью подходящие результаты."
                            ),
                        },
                        {
                            "role": "user",
                            "content": prompt,
                        },
                    ],
                    "temperature": 0.2,
                }
            )

        return response.choices[0].message.content

    @staticmethod
    def _build_prompt(question: str, context: str) -> str:
        return f"""
Вопрос пользователя:
{question}

Контекст из найденных документов:
{context}

Сформируй ответ на русском языке.

Правила ответа:
- Контекст выше предназначен только для анализа. Не копируй его структуру в ответ.
- Не перечисляй источники в формате "Документ 1", "Документ 2", "Источник 1", "Источник 2".
- Не дублируй карточки документов: номера, статусы, заявителей и продукцию пользователь увидит ниже в отдельных карточках.
- В основном ответе дай краткое аналитическое объяснение обычным текстом.
- Сгруппируй вывод по смыслу: что найдено, что подходит полностью, что подходит частично, что требует ручной проверки.
- Если найдено несколько подходящих документов, не расписывай каждый отдельным списком, а обобщи их.
- Номера документов упоминай только если это важно для итогового вывода.
- Если пользователь спрашивает про сертификаты, декларация не может считаться полностью подходящим результатом.
- Если пользователь спрашивает про декларации, сертификат не может считаться полностью подходящим результатом.
- Если пользователь спрашивает об актуальности, учитывай статус и срок действия.
- Если статус документа "Архивный", не называй его актуальным.
- Если полностью подходящих документов нет, прямо скажи об этом.
- Если запрос пользователя сформулирован широко, например "детская одежда", а найденные документы относятся к отдельным подкатегориям, например бельевые изделия, головные уборы, трикотажные изделия, не называй их полностью неподходящими. Укажи, что они подходят для отдельных категорий продукции и требуют ручной проверки на соответствие всей широкой категории запроса.
- Не делай вывод "полностью подходящих результатов не обнаружено", если найденные документы соответствуют типу документа, статусу и относятся к части запрошенной категории. В таком случае пиши, что найдены тематически или частично подходящие документы.
- В конце дай краткий итоговый вывод.

Желаемый стиль:
Короткий связный текст на 2-4 абзаца, без технического перечисления документов.

Ответ должен быть понятным обычному пользователю.
"""